```js
// in het entry point van je applicatie, vóór de velden op de pagina komen
import { VlInputFieldMaskedComponent } from '@domg-wc/components/form';

VlInputFieldMaskedComponent.setMasks({
    'custom-mask': {
        blocks: [8, 4],
        delimiters: ['-'],
        numericOnly: true,
        numeralPositiveOnly: true,
        regex: /^[0-9]{12}$/,
    },
});

// daarna in een template: <vl-input-field-masked mask="custom-mask"></vl-input-field-masked>
```
